let cur = "ru";

export const lang = ()=>cur;
export const langInfo = ()=>LANGS.find(l=>l.code===cur);

export function detectLang(saved){
  if(saved && UI[saved]) return saved;
  const prefs = (navigator.languages && navigator.languages.length) ? navigator.languages : [navigator.language || "en"];
  for(const p of prefs){ const c = String(p||"").slice(0,2).toLowerCase(); if(UI[c]) return c; }
  return "en";
}

export function setLang(code){
  cur = UI[code] ? code : "en";
  if(typeof document !== "undefined") document.documentElement.lang = cur;
}

export function t(key, vars){
  let s = UI[cur][key];
  if(s == null) s = UI.en[key];
  if(s == null) return key;
  if(vars) s = s.replace(/\{(\w+)\}/g, (m,k)=> vars[k] != null ? vars[k] : m);
  return s;
}

// Слово во множественном числе по правилам языка: tp("pl_places", 5) → «мест» / "places"
export function tp(key, n){
  const forms = UI[cur][key] || UI.en[key];
  let cat = "other";
  try{ cat = new Intl.PluralRules(cur).select(n); }catch(e){}
  return forms[cat] != null ? forms[cat] : forms.other;
}

export function fmtNum(n, digits){
  const d = digits || 0;
  try{ return new Intl.NumberFormat(cur, {minimumFractionDigits:d, maximumFractionDigits:d}).format(n); }
  catch(e){ return n.toFixed(d); }
}
